/**
 * frontend/src/components/CameraRecognition.jsx
 * ✅ Caméra PC portable contrôlée manuellement
 * ✅ Images brutes envoyées au backend
 * ✅ FaceBox + compteurs + feedback UX complets
 * ✅ Intervalle adaptatif (1500ms → 600ms)
 */

import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from '../api_service';

// ============ CONSTANTES ============
const CAPTURE_INTERVAL_DEFAULT = 1500; // ms (intervalle normal)
const CAPTURE_INTERVAL_FAST = 600;     // ms (intervalle rapide après détection)
const CONFIDENCE_THRESHOLD = 0.5;       // Seuil minimum d'affichage

// ============ COULEURS ============
const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const captureCanvasRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);
  const captureIntervalRef = useRef(CAPTURE_INTERVAL_DEFAULT);

  // ============ STATES ============
  const [autoMode, setAutoMode] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Résultats
  const [lastResult, setLastResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);

  // Compteurs et stats
  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [lastDetectionTime, setLastDetectionTime] = useState(null);
  const [frameCount, setFrameCount] = useState(0);

  /**
   * ✅ DÉMARRER CAMÉRA + BOUCLE AUTO
   */
  const startCamera = async () => {
    try {
      console.log('🎥 [CAMERA] Démarrage caméra...');
      setError(null);
      setLoading(true);

      // Vérifier support
      if (!navigator.mediaDevices?.getUserMedia) {
        throw new Error('getUserMedia non supporté par ce navigateur');
      }

      // Demander accès caméra
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: 'user',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      });

      console.log('✅ [CAMERA] Stream obtenu');
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        // Attendre que la vidéo soit prête
        videoRef.current.onloadedmetadata = () => {
          console.log('✅ [CAMERA] Vidéo prête');
          setCameraActive(true);
          setLoading(false);
          setAutoMode(true);
          setFrameCount(0);

          if (addNotification) {
            addNotification('✅ Caméra démarrée, scan auto lancé', 'success');
          }

          // Commencer la boucle de capture
          startCaptureLoop();
        };

        // Forcer le play
        try {
          await videoRef.current.play();
        } catch (err) {
          console.warn('⚠️ Play échoué, retry...', err);
          setTimeout(() => videoRef.current?.play().catch(() => {}), 500);
        }
      }

    } catch (err) {
      console.error('❌ [CAMERA] Erreur:', err.message);

      let errorMsg = err.message;
      if (err.name === 'NotAllowedError') {
        errorMsg = '❌ Permission refusée. Vérifiez les paramètres de caméra du navigateur.';
      } else if (err.name === 'NotFoundError') {
        errorMsg = '❌ Aucune caméra trouvée sur cet appareil.';
      } else if (err.name === 'NotReadableError') {
        errorMsg = '❌ Caméra occupée par une autre application.';
      }

      setError(errorMsg);
      setLoading(false);
      setCameraActive(false);
      setAutoMode(false);

      if (addNotification) {
        addNotification(errorMsg, 'error');
      }
    }
  };

  /**
   * ✅ BOUCLE DE CAPTURE AUTO
   */
  const startCaptureLoop = () => {
    console.log('▶️ [CAPTURE] Boucle de capture lancée');

    const captureFrame = async () => {
      if (!videoRef.current || !canvasRef.current) return;

      try {
        // Vérifier que vidéo a des dimensions
        if (videoRef.current.videoWidth === 0) {
          console.warn('⚠️ [CAPTURE] Vidéo pas encore prête');
          scheduleNextCapture(CAPTURE_INTERVAL_DEFAULT);
          return;
        }

        // Préparer canvas
        const canvas = canvasRef.current;
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        // Convertir en base64
        const imageBase64 = canvas.toDataURL('image/jpeg', 0.8);

        // Incrémenter compteur frames
        setFrameCount(prev => prev + 1);

        // Envoyer au backend
        console.log(`📤 [CAPTURE] Envoi frame...`);
        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        if (!data) {
          console.warn('⚠️ [CAPTURE] Pas de réponse du serveur');
          scheduleNextCapture(CAPTURE_INTERVAL_DEFAULT);
          return;
        }

        console.log(`📥 [CAPTURE] Réponse:`, {
          success: data.success,
          student: data.student,
          confidence: data.confidence?.toFixed(3),
          hasBox: !!data.face_box
        });

        // ✅ SUCCÈS: Étudiant reconnu
        if (data.success && data.student) {
          console.log(`✅ [CAPTURE] Étudiant trouvé: ${data.student}`);
          setSuccessCount(prev => prev + 1);

          handleSuccessResult(data, imageBase64);

          // Passer en mode rapide pour confirmer
          scheduleNextCapture(CAPTURE_INTERVAL_FAST);

        } 
        // ⚠️ FAIBLE CONFIANCE: Visage détecté mais peu confiant
        else if (!data.success && data.confidence >= CONFIDENCE_THRESHOLD) {
          console.log(`⚠️ [CAPTURE] Faible confiance: ${(data.confidence * 100).toFixed(1)}%`);

          handleWeakConfidenceResult(data, imageBase64);

          // Rester en mode normal
          scheduleNextCapture(CAPTURE_INTERVAL_DEFAULT);

        }
        // ❌ NON RECONNU: Pas de visage ou confiance très faible
        else {
          console.log(`❌ [CAPTURE] Pas de reconnaissance`);
          setErrorCount(prev => prev + 1);

          // Afficher l'image capturée quand même
          setCapturedImage(imageBase64);

          // Dessiner face box si disponible
          if (data.face_box) {
            drawFaceBox(canvas, data.face_box);
          }

          // Intervalle normal
          scheduleNextCapture(CAPTURE_INTERVAL_DEFAULT);
        }

      } catch (err) {
        console.error('❌ [CAPTURE] Erreur:', err.message);
        scheduleNextCapture(CAPTURE_INTERVAL_DEFAULT);
      }
    };

    const scheduleNextCapture = (interval) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      captureIntervalRef.current = interval;
      timeoutRef.current = setTimeout(captureFrame, interval);
    };

    // Première capture
    captureFrame();
  };

  /**
   * ✅ RÉSULTAT SUCCÈS
   */
  const handleSuccessResult = (data, imageBase64) => {
    setCapturedImage(imageBase64);
    setLastDetectionTime(new Date().toLocaleTimeString());

    setLastResult({
      success: true,
      student: data.student,
      email: data.email || 'N/A',
      confidence: (data.confidence * 100).toFixed(1),
      attendanceId: data.attendance_id,
      timestamp: new Date().toLocaleTimeString(),
      message: `✅ ${data.student} identifié avec ${(data.confidence * 100).toFixed(1)}% de confiance`
    });

    if (addNotification) {
      addNotification(`✅ ${data.student} détecté!`, 'success');
    }
  };

  /**
   * ✅ RÉSULTAT FAIBLE CONFIANCE
   */
  const handleWeakConfidenceResult = (data, imageBase64) => {
    setCapturedImage(imageBase64);
    setLastDetectionTime(new Date().toLocaleTimeString());

    setLastResult({
      success: false,
      student: 'Inconnu',
      email: 'N/A',
      confidence: (data.confidence * 100).toFixed(1),
      message: `⚠️ Visage détecté avec faible confiance (${(data.confidence * 100).toFixed(1)}%)`
    });

    if (addNotification) {
      addNotification('⚠️ Confiance faible - rapprochez-vous', 'warning');
    }
  };

  /**
   * ✅ CAPTURER UNE FOIS (bouton manuel)
   */
  const captureOnce = async () => {
    if (!videoRef.current || !captureCanvasRef.current) {
      setError('Caméra non disponible');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      console.log('📸 [CAPTURE_ONCE] Capture unique...');

      const canvas = captureCanvasRef.current;
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;

      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      // Envoyer au backend
      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data.success && data.student) {
        handleSuccessResult(data, imageBase64);
        setSuccessCount(prev => prev + 1);
      } else if (data.confidence >= CONFIDENCE_THRESHOLD) {
        handleWeakConfidenceResult(data, imageBase64);
      } else {
        setCapturedImage(imageBase64);
        setErrorCount(prev => prev + 1);
        setLastResult({
          success: false,
          student: 'Inconnu',
          message: '❌ Visage non reconnu'
        });
      }

    } catch (err) {
      console.error('❌ [CAPTURE_ONCE] Erreur:', err);
      setError(err.message);
      if (addNotification) {
        addNotification(`❌ Erreur: ${err.message}`, 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  /**
   * ✅ DESSINER FACE BOX
   */
  const drawFaceBox = (videoCanvas, faceBox) => {
    try {
      if (!canvasRef.current || !faceBox) return;

      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');

      // Récupérer les coordonnées
      const { x, y, width, height } = faceBox;

      // Tracer le rectangle (lime vert)
      ctx.strokeStyle = 'lime';
      ctx.lineWidth = 3;
      ctx.strokeRect(x, y, width, height);

      console.log('✅ [FACEBOX] Dessiné:', { x, y, width, height });
    } catch (err) {
      console.warn('⚠️ [FACEBOX] Erreur:', err.message);
    }
  };

  /**
   * ✅ ARRÊTER AUTO
   */
  const stopAuto = () => {
    console.log('⏹ [CAPTURE] Arrêt boucle');

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    setAutoMode(false);
  };

  /**
   * ✅ FERMER CAMÉRA COMPLÈTEMENT
   */
  const closeCamera = () => {
    console.log('🛑 [CAMERA] Fermeture');

    // Arrêter la boucle
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    // Arrêter le flux
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        console.log(`📹 Arrêt track ${track.kind}`);
        track.stop();
      });
      streamRef.current = null;
    }

    // Réinitialiser état
    setCameraActive(false);
    setAutoMode(false);
    setLoading(false);
    setError(null);
    setLastResult(null);
    setCapturedImage(null);
    setFrameCount(0);

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  /**
   * ✅ RESET RÉSULTATS
   */
  const resetResults = () => {
    console.log('🔄 Reset résultats');
    setLastResult(null);
    setCapturedImage(null);
    setError(null);
  };

  /**
   * ✅ CLEANUP AU DÉMONTAGE
   */
  useEffect(() => {
    return () => {
      console.log('🧹 [CLEANUP] Composant démonté');
      closeCamera();
    };
  }, []);

  // ============ RENDU ============
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* HEADER */}
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>
          <p style={styles.subtitle}>
            {!cameraActive
              ? 'Cliquez sur "Démarrer Auto" pour commencer'
              : autoMode
              ? '🔄 Scan automatique en cours...'
              : '⏸ Scan arrêté'}
          </p>
        </div>

        {/* VIDEO SECTION */}
        {cameraActive ? (
          <div style={styles.videoWrapper}>
            <video
              ref={videoRef}
              autoPlay
              muted
              playsInline
              style={styles.video}
            />

            {autoMode && (
              <div
                style={styles.scanBadge}
                aria-label="Scan en cours"
              >
                🔄 SCANNING
              </div>
            )}
          </div>
        ) : (
          <div style={styles.videoPlaceholder}>
            <p style={styles.placeholderText}>📹 Caméra non activée</p>
            <p style={styles.placeholderSubtext}>Cliquez sur "Démarrer Auto"</p>
          </div>
        )}

        {/* BOUTONS CONTRÔLE */}
        <div style={styles.controls}>
          {!cameraActive ? (
            <button
              onClick={startCamera}
              disabled={loading}
              style={{
                ...styles.btn,
                ...styles.btnSuccess,
                opacity: loading ? 0.6 : 1
              }}
              aria-label="Démarrer la caméra automatique"
            >
              {loading ? '⏳ Démarrage...' : '▶️ Démarrer Auto'}
            </button>
          ) : (
            <>
              <button
                onClick={captureOnce}
                disabled={loading}
                style={{
                  ...styles.btn,
                  ...styles.btnPrimary,
                  opacity: loading ? 0.6 : 1
                }}
                aria-label="Capturer une image unique"
              >
                {loading ? '⏳ Capture...' : '📸 Capturer Maintenant'}
              </button>

              {autoMode ? (
                <button
                  onClick={stopAuto}
                  style={{ ...styles.btn, ...styles.btnWarning }}
                  aria-label="Arrêter le scan automatique"
                >
                  ⏹ Arrêter Auto
                </button>
              ) : (
                <button
                  onClick={() => setAutoMode(true)}
                  style={{ ...styles.btn, ...styles.btnSuccess }}
                  aria-label="Reprendre le scan automatique"
                >
                  ▶️ Reprendre Auto
                </button>
              )}

              <button
                onClick={closeCamera}
                style={{ ...styles.btn, ...styles.btnDanger }}
                aria-label="Fermer la caméra"
              >
                🛑 Fermer Caméra
              </button>
            </>
          )}
        </div>

        {/* MESSAGE D'ERREUR */}
        {error && (
          <div style={styles.errorBox}>
            {error}
          </div>
        )}

        {/* RÉSULTAT */}
        {lastResult && (
          <div
            style={{
              ...styles.resultBox,
              borderLeftColor: lastResult.success ? COLORS.success : COLORS.warning,
              animation: 'fadeIn 0.3s ease-in'
            }}
          >
            <h2 style={styles.resultTitle}>
              {lastResult.success ? '✅' : '⚠️'} {lastResult.message}
            </h2>

            {/* GRILLE IMAGES */}
            <div style={styles.imagesGrid}>
              {/* IMAGE CAPTURÉE */}
              <div style={styles.imageBox}>
                <h3 style={styles.imageLabel}>📷 Photo Capturée</h3>
                {capturedImage ? (
                  <img
                    src={capturedImage}
                    alt="Captured"
                    style={styles.image}
                  />
                ) : (
                  <div style={styles.imagePlaceholder}>
                    Aucune capture disponible
                  </div>
                )}
              </div>

              {/* INFOS */}
              <div style={styles.infoBox}>
                <h3 style={styles.imageLabel}>📊 Détails</h3>
                <div style={styles.detailsGrid}>
                  <div style={styles.detailRow}>
                    <span style={styles.detailLabel}>👤 Nom:</span>
                    <span style={styles.detailValue}>{lastResult.student}</span>
                  </div>
                  <div style={styles.detailRow}>
                    <span style={styles.detailLabel}>📧 Email:</span>
                    <span style={styles.detailValue}>{lastResult.email}</span>
                  </div>
                  <div style={styles.detailRow}>
                    <span style={styles.detailLabel}>🎯 Confiance:</span>
                    <span
                      style={{
                        ...styles.detailValue,
                        color: lastResult.confidence >= 80 ? COLORS.success : COLORS.warning
                      }}
                    >
                      {lastResult.confidence}%
                    </span>
                  </div>
                  {lastResult.attendanceId && (
                    <div style={styles.detailRow}>
                      <span style={styles.detailLabel}>🆔 ID Présence:</span>
                      <span style={styles.detailValue}>{lastResult.attendanceId}</span>
                    </div>
                  )}
                  <div style={styles.detailRow}>
                    <span style={styles.detailLabel}>🕒 Heure:</span>
                    <span style={styles.detailValue}>{lastResult.timestamp}</span>
                  </div>
                </div>
              </div>
            </div>

            {/* BOUTON RESET */}
            <button
              onClick={resetResults}
              style={{ ...styles.btn, ...styles.btnPrimary, marginTop: '20px', width: '100%' }}
            >
              🔄 Nouvelle détection
            </button>
          </div>
        )}

        {/* SECTION DEBUG */}
        <div style={styles.debugBox}>
          <h4 style={styles.debugTitle}>📊 Statistiques</h4>
          <div style={styles.debugGrid}>
            <div>
              <span style={styles.debugLabel}>✅ Succès:</span>
              <span style={styles.debugValue}>{successCount}</span>
            </div>
            <div>
              <span style={styles.debugLabel}>❌ Erreurs:</span>
              <span style={styles.debugValue}>{errorCount}</span>
            </div>
            <div>
              <span style={styles.debugLabel}>📹 Frames:</span>
              <span style={styles.debugValue}>{frameCount}</span>
            </div>
            <div>
              <span style={styles.debugLabel}>⏱ Dernier scan:</span>
              <span style={styles.debugValue}>{lastDetectionTime || '--:--'}</span>
            </div>
          </div>
        </div>
      </div>

      {/* CANVAS CACHÉ */}
      <canvas ref={canvasRef} style={{ display: 'none' }} />
      <canvas ref={captureCanvasRef} style={{ display: 'none' }} />

      {/* ANIMATIONS CSS */}
      <style>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(-10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }
      `}</style>
    </div>
  );
};

